zonaCargada('f','78_-12',{"h:castillo-de-trujillo":{"epoca":"Castillos y fortalezas","resumen":"El castillo corona el cerro de la Cabeza del Zorro, en lo más alto de Trujillo. Es una alcazaba andalusí levantada entre los siglos IX y XII, de sillería de granito y con torres cuadradas; dos de ellas guardan la puerta, de arco de herradura.","ver_alli":["La puerta de arco de herradura, con la Virgen de la Victoria encima.","Baja a los aljibes árabes.","Sube al adarve: las vistas sobre Trujillo y la llanura son lo mejor de la visita.","Busca inscripciones árabes en algunos sillares."],"fuentes":["https://es.wikipedia.org/wiki/Castillo_de_Trujillo","https://es.wikipedia.org/wiki/Trujillo_(Espa%C3%B1a)","https://www.openstreetmap.org/?mlat=39.4624&mlon=-5.8824#map=18/39.4624/-5.8824","https://www.google.com/maps/place/?q=place_id:ChIJ9223FSGjFQ0RJQrs7Bod3iM"]},"h:plaza-mayor-de-trujillo":{"epoca":"Renacimiento","resumen":"La Plaza Mayor de Trujillo, rectangular y rodeada en buena parte de soportales, nació fuera de la muralla como lugar de artesanos y comerciantes. Desde el siglo XVI se llenó de palacios levantados con la riqueza que trajeron los indianos que volvieron de América.El más famoso es el palacio de la Conquista, empezado en 1562 por Hernando Pizarro y su esposa y sobrina Francisca Pizarro Yupanqui.","ver_alli":["El balcón de esquina del palacio de la Conquista, con los bustos de los Pizarro y el gran escudo.","La estatua ecuestre de Pizarro, frente a la iglesia de San Martín.","Pasea bajo los soportales y mira los escudos de las fachadas.","Acceso libre."],"fuentes":["https://es.wikipedia.org/wiki/Trujillo_(Espa%C3%B1a)","https://es.wikipedia.org/wiki/Palacio_de_la_Conquista","https://es.wikipedia.org/wiki/Estatua_ecuestre_de_Francisco_Pizarro","https://www.openstreetmap.org/?mlat=39.4607&mlon=-5.8815#map=18/39.4607/-5.8815","https://www.google.com/maps/place/?q=place_id:ChIJQX4vlSCjFQ0RrI_KYjrNkUY"]},"n:zepa-llanos-de-zorita-y-embalse-de-sierra-brava--badajoz":{"municipio":"Alcollarín","resumen":"Humedal en Alcollarín (Badajoz). Zona de Especial Protección para las Aves en la frontera entre Cáceres y Badajoz, estepas cerealistas con avutarda y el embalse de Sierra Brava como invernadero de grulla común. Rutas del catálogo que pasan cerca: VV de las Vegas del Guadiana y las Villuercas y Camino Natural Vía Verde Vegas del Guadiana."},"r:pr-cc-238-trujillo-trujillo--caceres":{"municipio":"Trujillo","resumen":"Sendero de pequeño recorrido (PR) lineal de 11,8 km en Trujillo (Cáceres). Acumula unos 91 m de subida, entre 423 y 528 m de altitud. Se calcula en 2 h 45 min de marcha.","web":"http://misendafedme.es/buscador-de-senderos/etapa/pr-cc-238-entre-puentes-llanos-y-berrocales","distancia_km":11.78,"desnivel_positivo_m":91,"tiempo_estimado_horas":2.75,"tipo_recorrido":"lineal","altitud_max_m":528,"esf":1},"r:camino-natural-del-guadiana-tramo-de-extremadura--badajoz":{"municipio":"Villanueva de la Serena","resumen":"Ruta lineal de 617 km en Villanueva de la Serena (Badajoz). Se divide en 47 etapas. Acumula unos 4.526 m de subida y 5.197 m de bajada, entre 150 y 719 m de altitud. Se calcula en 146 h 45 min de marcha en total. Atraviesa en parte la Reserva de la Biosfera La Siberia.","web":"https://www.mapa.gob.es/caminosnaturales","distancia_km":617.24,"desnivel_positivo_m":4526,"tiempo_estimado_horas":146.75,"tipo_recorrido":"lineal por etapas","altitud_max_m":719,"esf":2},"t:iglesia-de-san-pedro-apostol-villar-de-rena":{"municipio":"Villar de Rena","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Villar de Rena; el punto no marca el sitio exacto.","lat_pueblo":39.0771,"lon_pueblo":-5.8107,"resumen":"Pequeña iglesia tardogótica del siglo XV en el borde este del pueblo, junto a la carretera de Campo Lugar, de mampostería y piedra. Tiene una gran cabecera con bóveda de crucería estrellada y, bajo la torre, un baptisterio con un sillar fechado en 1560. Tras un incendio en 1986 aparecieron pinturas murales populares del siglo XVIII, ya restauradas, que imitan un retablo de doce casillas con la Anunciación, la Natividad y un Crucificado.","ver_alli":["Bóveda de crucería estrellada de la cabecera","Pinturas murales del siglo XVIII descubiertas en 1986","Sillar fechado en 1560 en el baptisterio"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Villar_de_Rena"]},"t:iglesia-de-nuestra-senora-de-los-angeles-rena":{"municipio":"Rena","resumen":"Iglesia parroquial de Rena, en la plaza de España.","visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Rena","https://nominatim.openstreetmap.org/"]},"t:castillo-de-la-encomienda-villanueva-de-la-serena":{"municipio":"Villanueva de la Serena","resumen":"Restos de un castillo de la Orden de Alcántara, también llamado de Castelnovo, sobre un cerro al norte del Guadiana a unos 8 km de la ciudad, levantado tras la conquista de 1232 sobre una fortaleza musulmana. Lo que se ve es del siglo XIV: dos torres en el flanco sur, una cuadrada y otra redonda, unidas por andenes y escaleras, y una barbacana. A finales del XV se le añadió otro recinto con cubos cilíndricos en las esquinas.","ver_alli":["Torre prismática y torre cilíndrica comunicadas","Barbacana con cubos"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Castillo_de_la_Encomienda_(Villanueva_de_la_Serena)","https://es.wikipedia.org/wiki/Villanueva_de_la_Serena"]},"t:castillo-palacio-de-los-altamirano-orellana-la-vieja":{"municipio":"Orellana la Vieja","resumen":"Casa fuerte de los señores de Orellana, con origen en una torre de hacia 1280 citada ya en 1340. Hacia mediados del siglo XVI perdió su carácter defensivo y se convirtió en palacio, con un patio plateresco hoy desaparecido. Tras la Guerra Civil se perdieron la fachada, el patio y varias torres; queda la torre del homenaje, un torreón circular y otros restos, que la Junta ha ido rehabilitando.","ver_alli":["Torre del homenaje","Escudo de los Orellana con diez roeles","Torreón circular"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Orellana_la_Vieja","https://turismoextremadura.juntaex.es/en/explora/The-Altamirano-Castle-Palace"]},"t:convento-de-san-benito-de-las-dominicas-orellana-la-vieja":{"municipio":"Orellana la Vieja","resumen":"Convento renacentista fundado por Teresa de Meneses, que obtuvo licencia en 1528; hacia 1540 ya estaba en obras. Lo habitaron monjas dominicas de clausura hasta la desamortización de 1836. Rehabilitado por el Ayuntamiento, hoy es centro cultural con biblioteca, auditorio y sala de exposiciones.","ver_alli":["Fachada con escudos de los Orellana y de la Orden de Alcántara","Trascoro con esgrafiados de animales mitológicos","Aljibe con bóveda de ladrillo bajo el trascoro"],"visita":"desconocido","fuentes":["https://es.wikipedia.org/wiki/Orellana_la_Vieja","https://www.guiarepsol.com/es/fichas/monumento/convento-de-san-benito-20678/"]},"t:iglesia-de-la-inmaculada-concepcion-orellana-la-vieja":{"municipio":"Orellana la Vieja","resumen":"Iglesia parroquial encargada en 1570 al arquitecto trujillano Francisco Becerra, de una sola nave tipo salón. Tiene cabecera semicircular cubierta con una bóveda de cuarto de esfera avenerada y la nave con una rica armadura de madera de finales del siglo XVI. La portada de los pies lleva la fecha de 1659 y encima una ventana plateresca.","ver_alli":["Armadura de madera de siete paños","Cristo de marfil de finales del siglo XVI atribuido a Gaspar Núñez Delgado","Cruz procesional de plata del siglo XVI"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Orellana_la_Vieja"]},"t:restos-del-convento-del-paular-orellana-la-vieja":{"municipio":"Orellana la Vieja","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Orellana la Vieja; el punto no marca el sitio exacto.","lat_pueblo":39.0053,"lon_pueblo":-5.5342,"resumen":"Restos de un antiguo convento de los que se conserva un ventanal.","visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Orellana_la_Vieja"]},"t:arquitectura-popular-de-las-calles-real-palacio-y-orellanita-orellana-la-vieja":{"municipio":"Orellana la Vieja","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Orellana la Vieja; el punto no marca el sitio exacto.","lat_pueblo":39.0053,"lon_pueblo":-5.5342,"resumen":"Casas de arquitectura popular sin catalogar en las calles Real, Palacio y Orellanita.","visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Orellana_la_Vieja"]},"t:castillo-palacio-de-los-garcia-bejarano-orellana-de-la-sierra":{"municipio":"Orellana de la Sierra","resumen":"Fortaleza de finales del siglo XIII levantada, según la tradición, por Álvar García Bejarano, a quien Enrique II dio el señorío de Orellana de la Sierra; la familia cambió luego su apellido por Orellana. Era de planta rectangular con torres en las esquinas; hoy queda bien visible un lienzo de muralla con dos torres. Está en la parte alta del pueblo, restaurado y de uso residencial.","ver_alli":["Escudo de los Bejarano de finales del siglo XVI sobre la puerta","Lienzo de muralla con dos torres"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Orellana_de_la_Sierra","https://es.wikipedia.org/wiki/Castillo_de_Orellana_de_la_Sierra"]},"t:iglesia-de-nuestra-senora-de-la-jara-acedera":{"municipio":"Acedera","resumen":"Iglesia parroquial del pueblo, dedicada a Nuestra Señora de la Jara.","visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Acedera_(Badajoz)"]},"t:poblado-de-colonizacion-de-los-guadalperales-acedera":{"municipio":"Acedera","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Acedera; el punto no marca el sitio exacto.","lat_pueblo":39.0769,"lon_pueblo":-5.5722,"resumen":"Pueblo de colonización fundado a finales de 1959 dentro del Plan Badajoz, tras expropiarse las fincas del Guadalperal y del Pasarón. Su trazado responde al modelo de estos pueblos nuevos: calles rectas y anchas y casas de colonos con grandes corrales y dependencias para el ganado y los aperos. La iglesia está dedicada a San Fulgencio.","ver_alli":["Trazado ortogonal típico de los pueblos de colonización","Casas de colonos con corrales","Iglesia de San Fulgencio en la plaza"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Los_Guadalperales"]},"t:iglesia-de-santa-ana-santa-ana":{"municipio":"Santa Ana","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Santa Ana; el punto no marca el sitio exacto.","lat_pueblo":39.309,"lon_pueblo":-5.9902,"resumen":"Iglesia parroquial del siglo XVI, de estilo barroco, con un pórtico ante las puertas. Dentro, las bóvedas descansan sobre arcos de medio punto y hay un retablo del siglo XVIII.","ver_alli":["Pórtico de entrada","Retablo del siglo XVIII"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Santa_Ana_(Cáceres)"]},"t:casa-de-pizarro-santa-ana":{"municipio":"Santa Ana","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Santa Ana; el punto no marca el sitio exacto.","lat_pueblo":39.309,"lon_pueblo":-5.9902,"resumen":"Casa del siglo XVI de los Pizarro-Carvajal, una rama de los Pizarro de Trujillo, conquistadores del Perú. Conserva los escudos de armas de la familia en piedra sobre la puerta y la fachada, aunque el edificio ha sido muy transformado.","ver_alli":["Escudos de los Pizarro-Carvajal en la fachada"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Santa_Ana_(Cáceres)"]},"t:iglesia-de-san-pedro-apostol-robledillo-de-trujillo":{"municipio":"Robledillo de Trujillo","resumen":"Iglesia parroquial del pueblo, dedicada a San Pedro.","visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Robledillo_de_Trujillo","https://www.openstreetmap.org/"]},"t:iglesia-de-nuestra-senora-de-la-asuncion-la-cumbre":{"municipio":"La Cumbre","resumen":"Iglesia parroquial de La Cumbre.","visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/La_Cumbre_(Cáceres)"]},"t:ermita-de-san-gregorio-la-cumbre":{"municipio":"La Cumbre","resumen":"Ermita dedicada a San Gregorio.","visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/La_Cumbre_(Cáceres)"]},"t:palacio-de-pedro-barrantes-la-cumbre":{"municipio":"La Cumbre","posicion_nota":"Ubicación sin confirmar: está en el pueblo de La Cumbre; el punto no marca el sitio exacto.","lat_pueblo":39.405,"lon_pueblo":-5.9771,"resumen":"Casa palaciega de Pedro Barrantes, entre los principales monumentos del pueblo.","visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/La_Cumbre_(Cáceres)"]},"t:rollo-de-la-cumbre-la-cumbre":{"municipio":"La Cumbre","resumen":"Rollo de justicia de la villa.","visita":"acceso libre","fuentes":["https://es.wikipedia.org/wiki/La_Cumbre_(Cáceres)"]},"t:iglesia-de-la-degollacion-de-san-juan-bautista-ibahernando":{"municipio":"Ibahernando","resumen":"Gran iglesia parroquial levantada entre finales del siglo XV y la primera mitad del XVI, quizá sobre un templo altomedieval, y restaurada a fondo en 2006. Se entra por un pórtico de cuatro arcos sobre columnas toscanas de finales del XVI, y la portada lleva un escudo episcopal en el frontón. Lo más curioso es la pila bautismal del siglo XV, apoyada desde el XVII sobre una lápida funeraria romana con inscripción.","ver_alli":["Pila bautismal sobre un cipo funerario romano con inscripción","Lienzo de la Degollación de San Juan, de principios del siglo XVIII","Púlpito de mediados del siglo XVI"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Ibahernando"]},"t:basilica-visigoda-de-santa-maria-ibahernando":{"municipio":"Ibahernando","resumen":"Restos de una basílica visigoda consagrada por el obispo Oroncio hacia abril del año 635, según su lápida. La excavó el arqueólogo Enrique Cerrillo en 1973. Está en una ladera a unos 540 metros de altitud, en las afueras.","ver_alli":["Planta de la basílica visigoda excavada"],"visita":"desconocido","fuentes":["https://es.wikipedia.org/wiki/Ibahernando","https://es.wikipedia.org/wiki/Basílica_visigoda_de_Santa_María_de_Ibahernando"]},"t:ermita-de-nuestra-senora-de-la-jara-ibahernando":{"municipio":"Ibahernando","resumen":"Ermita junto al camino de Santa Ana, a unos tres kilómetros al suroeste del pueblo, cerca de la laguna donde la tradición sitúa la aparición de la Virgen. Ya en 1791 se iba allí en procesión tres veces al año, y hoy es la romería principal, a finales de abril o primeros de mayo.","ver_alli":["Laguna de la aparición, a unos 500 metros"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Ibahernando"]},"t:arco-de-tia-juliana-ibahernando":{"municipio":"Ibahernando","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Ibahernando; el punto no marca el sitio exacto.","lat_pueblo":39.3167,"lon_pueblo":-5.9167,"resumen":"Arco popular del casco urbano, de 1914.","visita":"acceso libre","fuentes":["https://es.wikipedia.org/wiki/Ibahernando"]},"t:palacio-de-los-carvajal-ibahernando":{"municipio":"Ibahernando","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Ibahernando; el punto no marca el sitio exacto.","lat_pueblo":39.3167,"lon_pueblo":-5.9167,"resumen":"Palacio abandonado de la familia Carvajal.","visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Ibahernando"]},"t:casa-del-conde-ibahernando":{"municipio":"Ibahernando","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Ibahernando; el punto no marca el sitio exacto.","lat_pueblo":39.3167,"lon_pueblo":-5.9167,"resumen":"Casona renacentista construida con dinero llegado de América.","visita":"exterior libre","fuentes":["https://turismoextremadura.juntaex.es/en/explora/Ibahernando-00001"]},"t:iglesia-de-santiago-apostol-miajadas":{"municipio":"Miajadas","resumen":"Gran iglesia exenta de cruz latina, levantada desde mediados del siglo XVI bajo la dirección de Juan de Ezquerra y terminada a principios del XVII, con un crucero casi tan largo como la nave. Conserva de la iglesia primitiva una portada gótica a los pies, con arco apuntado en alfiz decorado con rosetas y bolas. Es Bien de Interés Cultural desde 1994.","ver_alli":["Portada gótica de los pies con alfiz y bolas","Portada renacentista con hornacina avenerada","Enorme crucero de sillería"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Iglesia_de_Santiago_(Miajadas)","https://sites.google.com/educarex.es/patrimoniomiajadas/inicio/parroquia-de-santiago-ap%C3%B3stol"]},"t:palacio-del-obispo-solis-y-museo-masa-solis-miajadas":{"municipio":"Miajadas","resumen":"Casa palacio neoclásica que conserva elementos anteriores, como una ventana de esquina con arco apuntado y balcón y un blasón barroco del obispo Solís, de la Orden de Santiago. De la fachada colgaban cadenas rotas, señal del derecho de asilo. Hoy alberga dependencias culturales municipales y el museo dedicado al pintor miajadeño José Masa Solís.","ver_alli":["Ventana esquinada con balcón","Escudo episcopal con capelo, cruz de Santiago y niños con báculo y mitra","Museo del pintor José Masa Solís"],"visita":"horario o cita previa","fuentes":["https://sites.google.com/educarex.es/patrimoniomiajadas/inicio/palacio-del-obispo-sol%C3%ADs/palacio-obispo-sol%C3%ADs","https://es.wikipedia.org/wiki/Miajadas"]},"t:picota-o-rollo-jurisdiccional-miajadas":{"municipio":"Miajadas","resumen":"Rollo levantado tras concederse a Miajadas el título de villa en 1734, que la independizó de Medellín. Se hizo con piedras reutilizadas de yacimientos prehistóricos, y sus gradas tienen cazoletas que podrían ser del Calcolítico o la Edad del Bronce. Mario Roso de Luna las estudió y las interpretó como escritura y luego como ábacos o tableros de juego.","ver_alli":["Cazoletas prehistóricas en las gradas"],"visita":"acceso libre","fuentes":["https://sites.google.com/educarex.es/patrimoniomiajadas/inicio/rollo-jurisdiccional/picota","https://es.wikipedia.org/wiki/Miajadas","https://www.openstreetmap.org/"]},"t:ermita-de-san-bartolome-miajadas":{"municipio":"Miajadas","resumen":"Ermita a unos 5 km del pueblo, escenario de la romería del Lunes de Pascua y de la recreación de la batalla de la Degollada de 1809. Tiene nave de tres tramos, camarín, pórtico con bancos, espadaña y dos cúpulas con linterna. En un escalón de la puerta de los pies hay grabado un tablero de alquerque de doce, de los pocos que se conservan en Extremadura.","ver_alli":["Tablero de alquerque grabado en el escalón","Retablo con San Blas y San Marcos","Pórtico con bancos"],"visita":"exterior libre","fuentes":["https://sites.google.com/educarex.es/patrimoniomiajadas/inicio/ermita-de-san-bartolom%C3%A9/ermita-de-san-bartolom%C3%A9","https://es.wikipedia.org/wiki/Miajadas","https://www.openstreetmap.org/"]},"t:iglesia-de-nuestra-senora-de-belen-miajadas":{"municipio":"Miajadas","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Miajadas; el punto no marca el sitio exacto.","lat_pueblo":39.1528,"lon_pueblo":-5.9081,"resumen":"Iglesia de una nave con óculo tetralobulado y portada de arco rebajado con escudo coronado y el anagrama del Ave María; Roso de Luna estudió en 1904 piedras con cazoletas de sus muros.","visita":"horario de culto","fuentes":["https://sites.google.com/educarex.es/patrimoniomiajadas/inicio/iglesia-de-ntr-sra-de-bel%C3%A9n/iglesia-de-bel%C3%A9n","https://es.wikipedia.org/wiki/Miajadas"]},"t:casa-de-los-casillas-iniguez-miajadas":{"municipio":"Miajadas","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Miajadas; el punto no marca el sitio exacto.","lat_pueblo":39.1528,"lon_pueblo":-5.9081,"resumen":"Casa señorial citada entre los monumentos civiles de Miajadas.","visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Miajadas","https://www.tuscasasrurales.com/que-ver-en-miajadas-1778.htm"]},"t:iglesia-de-nuestra-senora-de-la-asuncion-escurial":{"municipio":"Escurial","resumen":"Iglesia parroquial del siglo XVI. Guarda la talla policromada del Cristo de la Agonía o del Desamparo, del siglo XVII, considerada una obra maestra de la imaginería española, comparable a las de Montañés y Mena. Su fiesta es el 14 de septiembre.","ver_alli":["Cristo de la Agonía, talla del siglo XVII"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Escurial"]},"t:ermita-de-los-santos-martires-escurial":{"municipio":"Escurial","resumen":"Ermita junto al camino del cementerio.","visita":"exterior libre","fuentes":["https://www.openstreetmap.org/"]},"t:iglesia-de-santa-maria-la-mayor-trujillo":{"municipio":"Trujillo","resumen":"Templo románico tardío empezado en el siglo XIII, probablemente sobre la mezquita mayor, y ampliado en gótico en los siglos XV y XVI; fue el templo principal de la villa y guarda los enterramientos de los grandes linajes trujillanos. Su retablo mayor tiene 25 tablas pintadas hacia 1480-1490 por Fernando Gallego y el Maestro Bartolomé, restauradas en 2004-2005. La torre Julia, románica, se derribó en 1871 y se reconstruyó a finales del siglo XX; uno de sus capiteles nuevos lleva tallado el escudo del Athletic Club.","ver_alli":["Retablo de Fernando Gallego con 25 tablas hispanoflamencas","Coro plateresco de Sancho de Cabrera (1550)","Capitel con el escudo del Athletic Club en la torre"],"visita":"horario o cita previa","fuentes":["https://es.wikipedia.org/wiki/Iglesia_de_Santa_María_la_Mayor_(Trujillo)","https://es.wikipedia.org/wiki/Trujillo_(España)"]},"t:alcazar-de-luis-de-chaves-el-viejo-trujillo":{"municipio":"Trujillo","resumen":"Casa fuerte del siglo XIV adosada a la muralla junto a la puerta de Santiago, a la que defiende con su gran torre del homenaje. La reconstruyó en el siglo XV Luis de Chaves con vanos góticos de arco conopial y escudos. Aquí se alojaron varias veces los Reyes Católicos entre 1477 y 1479, y en 1479 se reunió en ella el Consejo de Castilla que reconoció a Fernando como rey de Aragón.","ver_alli":["Torre del homenaje con ventana mudéjar de ladrillo","Fachada oriental con arcos conopiales y tres escudos de los Chaves","Puerta de la calle Ballesteros con mascarones"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Alcázar_de_Luis_de_Chaves_el_Viejo","https://es.wikipedia.org/wiki/Trujillo_(España)"]},"t:palacio-de-los-orellana-pizarro-trujillo":{"municipio":"Trujillo","resumen":"Palacio renacentista con detalles platerescos de mediados del siglo XVI, obra de Alonso Becerra para Juan de Orellana Pizarro, conquistador del Perú y primo de Francisco Pizarro. Aprovecha dos torres de una casa fuerte anterior, unidas por un gran arco que forma un pórtico elevado, y encima una galería de columnas jónicas con niños tenantes que sostienen los escudos. Es Bien de Interés Cultural y hoy es colegio y casa madre de una congregación.","ver_alli":["Galería renacentista con balaustres y niños tenantes","Escudo partido de Orellana y Pizarro en el frontón"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Palacio_de_los_Orellana_Pizarro","https://es.wikipedia.org/wiki/Trujillo_(España)"]},"t:casa-museo-de-pizarro-trujillo":{"municipio":"Trujillo","resumen":"Museo en la casa solariega donde, según algunos historiadores, nació Francisco Pizarro, con portada que lleva el escudo de la familia. La planta baja recrea una casa de la época con muebles y documentos, y la alta explica la conquista del Perú, el imperio inca y la vida colonial. Tiene un patio con plantas americanas.","ver_alli":["Casa recreada de la época","Exposición sobre el Tahuantinsuyo y la conquista del Perú","Patio con plantas americanas"],"visita":"horario o cita previa","fuentes":["https://es.wikipedia.org/wiki/Casa-museo_de_Pizarro","https://es.wikipedia.org/wiki/Trujillo_(España)"]},"t:alcazar-de-los-bejarano-trujillo":{"municipio":"Trujillo","resumen":"Casa fuerte del siglo XIII que defendía la puerta del Triunfo, reconstruida en el siglo XV. Los Bejarano llegaron desde Beja para la conquista de Trujillo. Quedan dos torres desmochadas, una con la base de ladrillo mudéjar, y sobre la puerta el escudo con el lema «Sub umbram alarum protege nos».","ver_alli":["Escudo con el lema latino sobre la puerta","Torre con base mudéjar de ladrillo"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Alcázar_de_los_Bejarano","https://es.wikipedia.org/wiki/Trujillo_(España)"]},"t:alcazarejo-de-los-altamirano-trujillo":{"municipio":"Trujillo","resumen":"Pequeña casa fuerte del siglo XIII adosada a la muralla, con dos torres desmochadas y el escudo de los Altamirano entre ellas.","visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Alcazarejo_de_los_Altamirano"]},"t:iglesia-de-santiago-trujillo":{"municipio":"Trujillo","resumen":"Iglesia de la villa vieja junto a la puerta de Santiago y el alcázar de los Chaves; de ella salía en procesión el Cristo de las Aguas en las rogativas por lluvia.","visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Trujillo_(España)","https://es.wikipedia.org/wiki/Ermita_de_San_Lázaro_(Trujillo)","https://www.wikidata.org/wiki/Q99296172"]},"t:torre-del-alfiler-centro-de-interpretacion-de-la-historia-de-trujillo-trujillo":{"municipio":"Trujillo","resumen":"Torre que alberga el centro de interpretación que repasa la historia de la ciudad.","visita":"horario o cita previa","fuentes":["https://redex.org/storage/media/documents/617/12-web-folleto-miajadas.pdf"]},"t:museo-de-la-coria-trujillo":{"municipio":"Trujillo","resumen":"Museo en el antiguo convento de San Francisco el Real de la Coria, del siglo XV, sede de la Fundación Xavier de Salas. Está dedicado a la relación entre Extremadura e Iberoamérica.","ver_alli":["Antiguo convento franciscano del siglo XV"],"visita":"horario o cita previa","fuentes":["https://es.wikipedia.org/wiki/Trujillo_(España)","https://redex.org/storage/media/documents/617/12-web-folleto-miajadas.pdf"]},"t:museo-del-traje-enrique-elias-trujillo":{"municipio":"Trujillo","resumen":"Museo con trajes de grandes modistos del siglo XX.","visita":"horario o cita previa","fuentes":["https://es.wikipedia.org/wiki/Trujillo_(España)","https://redex.org/storage/media/documents/617/12-web-folleto-miajadas.pdf"]},"t:museo-rural-y-etnografico-de-huertas-de-animas-trujillo":{"municipio":"Trujillo","resumen":"Museo etnográfico en el arrabal de Huertas de Ánimas que explica la vida rural tradicional.","visita":"horario o cita previa","fuentes":["https://es.wikipedia.org/wiki/Trujillo_(España)","https://redex.org/storage/media/documents/617/12-web-folleto-miajadas.pdf"]},"t:ermita-de-san-lazaro-trujillo":{"municipio":"Trujillo","resumen":"Ermita de 1498 levantada fuera de la ciudad como lazareto para los enfermos de peste. Hoy está dedicada al Cristo de la Salud, crucificado del siglo XVI y patrón de Trujillo junto a la Virgen de la Victoria. En la sacristía hay un exvoto de 1872 de un vecino que se cayó desde lo alto del castillo, y cada mayo se celebra la «puja de San Lázaro».","ver_alli":["Cristo de la Salud (siglo XVI)","Exvoto de 1872 de la caída desde el castillo","Cruz de piedra con Cristo yacente en el jardín"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Ermita_de_San_Lázaro_(Trujillo)"]},"t:ermita-de-santa-ana-y-posito-trujillo":{"municipio":"Trujillo","resumen":"Ermita de 1732 mandada construir por el obispo Francisco Laso de la Vega en un cerrillo de las afueras, con un pósito para guardar grano junto a ella. La atacaron las tropas francesas en 1809 y está en ruinas desde entonces, en la Lista Roja de Hispania Nostra desde 2013. En 2006 se rodaron aquí escenas de la película «Teresa, el cuerpo de Cristo». Desde el cerro hay una buena vista de la ciudad y el castillo.","ver_alli":["Estructura casi íntegra de la ermita en ruinas","Pósito de grano contiguo","Vista de Trujillo con el castillo al fondo"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Ermita_de_Santa_Ana_(Trujillo)"]},"t:ermita-de-la-virgen-de-la-coronada-trujillo":{"municipio":"Trujillo","resumen":"Ruinas de una ermita construida hacia 1274, según una inscripción de su portada, atribuida a Gil de Cuéllar; se reformó en 1525-1529 y se usó hasta 1687. Era el destino de una romería desde la ciudad el tercer día de Pascua. Aunque una leyenda la vincula a los templarios, no hay pruebas. Su imagen, una Virgen tardorrománica del siglo XIII, está hoy en la iglesia de San Martín.","ver_alli":["Inscripción con la fecha en la portada","Muros de la ermita medieval"],"visita":"desconocido","fuentes":["https://es.wikipedia.org/wiki/Ermita_de_la_Virgen_de_la_Coronada_(Trujillo)"]},"t:rollo-de-trujillo-trujillo":{"municipio":"Trujillo","resumen":"Rollo o picota tardogótico de 1497 con el escudo de los Reyes Católicos y rematado por un pináculo con cruz de flor de lis. Estuvo primero en el centro de la actual plaza Mayor y ha cambiado varias veces de sitio; hoy está en la plaza del Campillo.","ver_alli":["Escudo de los Reyes Católicos","Remate con cruz de flor de lis"],"visita":"acceso libre","fuentes":["https://es.wikipedia.org/wiki/Rollo_de_Trujillo"]},"t:iglesia-de-santo-domingo-de-guzman-villamesias":{"municipio":"Villamesías","resumen":"Iglesia parroquial del pueblo, dedicada a Santo Domingo de Guzmán.","visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Villamesías"]},"t:iglesia-de-san-bartolome-puerto-de-santa-cruz":{"municipio":"Puerto de Santa Cruz","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Puerto de Santa Cruz; el punto no marca el sitio exacto.","lat_pueblo":39.3163,"lon_pueblo":-5.8588,"resumen":"Iglesia parroquial del siglo XVI con retablos del siglo XVIII. Lo mejor son la pila bautismal y el púlpito, de gótico final y gran calidad. Conserva también cálices, custodias y otras piezas de orfebrería.","ver_alli":["Púlpito de gótico final","Pila bautismal gótica","Retablos del siglo XVIII"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Puerto_de_Santa_Cruz"]},"t:cristo-de-la-misericordia-puerto-de-santa-cruz":{"municipio":"Puerto de Santa Cruz","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Puerto de Santa Cruz; el punto no marca el sitio exacto.","lat_pueblo":39.3163,"lon_pueblo":-5.8588,"resumen":"Cristo crucificado tallado en cantería sobre una gran masa de granito, en un antiguo cruce de caminos. Según la tradición, de él viene el nombre del pueblo.","ver_alli":["Crucifijo de granito sobre un gran bolo"],"visita":"acceso libre","fuentes":["https://es.wikipedia.org/wiki/Puerto_de_Santa_Cruz"]},"t:cano-de-la-plaza-puerto-de-santa-cruz":{"municipio":"Puerto de Santa Cruz","resumen":"Fuente del siglo XVI en la plaza del Caño, con los escudos de los Vargas Carvajal; ya no da agua.","visita":"acceso libre","fuentes":["https://es.wikipedia.org/wiki/Puerto_de_Santa_Cruz","https://www.openstreetmap.org/"]},"t:iglesia-de-la-vera-cruz-santa-cruz-de-la-sierra":{"municipio":"Santa Cruz de la Sierra","resumen":"Iglesia parroquial grande, de mampostería y sillería de granito, que según los indicios ocupa el lugar de una mezquita levantada sobre una basílica visigoda que a su vez aprovechó un templo romano. Es Bien de Interés Cultural desde 1974. Guarda un púlpito poligonal de finales del siglo XV, pila bautismal del XVI e imágenes barrocas traídas del convento de San Joaquín, y una Virgen de Cotoca donada por la ciudad boliviana en 2023.","ver_alli":["Púlpito poligonal de finales del siglo XV","Santa Rita de Casia, talla del siglo XVII","Virgen de la Consolación o «de la Correa»"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Santa_Cruz_de_la_Sierra_(España)","https://www.wikidata.org/wiki/Q43111520"]},"t:convento-de-san-joaquin-santa-cruz-de-la-sierra":{"municipio":"Santa Cruz de la Sierra","resumen":"Convento agustino fundado en 1629 por Juan de Chaves y Mendoza. La iglesia es de cruz latina con bóveda de cañón y cúpula sobre pechinas, y conserva restos de pinturas murales con motivos vegetales, geométricos y figuras. De sus imágenes queda una pequeña talla de granito de San Agustín, patrón del pueblo, de hacia 1700.","ver_alli":["Restos de pinturas murales","Talla de granito de San Agustín (hacia 1700)"],"visita":"desconocido","fuentes":["https://es.wikipedia.org/wiki/Santa_Cruz_de_la_Sierra_(España)","https://www.wikidata.org/wiki/Q52854948"]},"t:iglesia-de-san-juan-bautista-abertura":{"municipio":"Abertura","resumen":"Iglesia parroquial del siglo XV.","visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Abertura_(Cáceres)","https://www.wikidata.org/wiki/Q115920085"]},"t:ermita-de-santa-ana-abertura":{"municipio":"Abertura","resumen":"Ermita a la que se va en romería en las fiestas patronales del 25 y 26 de julio.","visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Abertura_(Cáceres)","https://www.openstreetmap.org/"]},"t:iglesia-de-nuestra-senora-de-los-angeles-campo-lugar":{"municipio":"Campo Lugar","resumen":"Iglesia parroquial sencilla, de nave central con capillas laterales, que pese a muchas reformas puede datar de finales del siglo XV. Su rasgo más curioso es la torre, exenta pero unida al templo por un arco. Dentro guarda un retablo mayor barroco.","ver_alli":["Torre exenta unida a la iglesia por un arco","Retablo barroco de columnas salomónicas con racimos","Talla de la Asunción con pinturas de San Juan Bautista y San Blas"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Campo_Lugar"]},"t:castillo-palacio-de-los-pizarro-conquista-de-la-sierra":{"municipio":"Conquista de la Sierra","resumen":"Casa fuerte construida en el siglo XVI por Hernando Pizarro y Francisca Pizarro Yupanqui, hermano e hija del conquistador Francisco Pizarro, en el extremo este del pueblo. Tiene tres plantas de mampostería con sillares en las partes nobles, y la torre pudo ser anterior, usada para vigilar la dehesa. Los franceses lo quemaron en la Guerra de la Independencia y hoy está en ruina, sin techumbre.","ver_alli":["Torre, posiblemente anterior al palacio","Sillería en las partes nobles","Vínculo directo con la familia de Francisco Pizarro"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Castillo_palacio_de_los_Pizarro","https://es.wikipedia.org/wiki/Conquista_de_la_Sierra"]},"t:iglesia-de-san-lorenzo-martir-conquista-de-la-sierra":{"municipio":"Conquista de la Sierra","resumen":"Iglesia parroquial del pueblo, con una torre que se ve desde lejos.","visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Conquista_de_la_Sierra"]},"t:iglesia-de-santiago-apostol-garciaz":{"municipio":"Garciaz","resumen":"Templo en lo más alto del pueblo, encargado en 1545 por el obispo de Plasencia Gutierre de Vargas Carvajal al maestro trujillano Sancho de Cabrera, sobre una cabecera de finales del siglo XV. Es Bien de Interés Cultural. Conserva un altar de azulejería talaverana de comienzos del XVII y, en su interior, una lápida romana dedicada al dios Marte.","ver_alli":["Altar de la Virgen del Rosario en azulejo de Talavera con panel de la Anunciación","Portadas renacentistas con conchas y escudos del obispo","Inscripción romana votiva a Marte"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Iglesia_de_Santiago_Apóstol_(Garciaz)","https://es.wikipedia.org/wiki/Garciaz"]},"t:rollo-jurisdiccional-de-garciaz-garciaz":{"municipio":"Garciaz","resumen":"Rollo de 1565 en la plaza de España, de granito de las canteras de Trujillo. Se alza sobre cinco escalones circulares y remata en un pináculo con una pieza en forma de bellota.","ver_alli":["Gradería circular de cinco escalones","Cuatro mamelones con roleos","Remate en forma de bellota"],"visita":"acceso libre","fuentes":["https://es.wikipedia.org/wiki/Garciaz"]},"t:pozo-de-la-nieve-de-garciaz-garciaz":{"municipio":"Garciaz","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Garciaz; el punto no marca el sitio exacto.","lat_pueblo":39.4136,"lon_pueblo":-5.6267,"resumen":"Restos de un pozo de nieve en el paraje de Las Caballerías, documentado desde el siglo XVI. La nieve se prensaba en capas con helechos o paja y el hielo se vendía en bloques por toda la comarca de Trujillo; fue una de las mayores fuentes de ingresos del concejo.","ver_alli":["Restos del pozo","Uno de los pocos que abastecían de hielo a la comarca trujillana"],"visita":"desconocido","fuentes":["https://es.wikipedia.org/wiki/Garciaz"]},"t:fuente-del-cano-garciaz":{"municipio":"Garciaz","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Garciaz; el punto no marca el sitio exacto.","lat_pueblo":39.4136,"lon_pueblo":-5.6267,"resumen":"Fuente de granito de 1795 junto al Charco del Caño, con una placa a modo de escudo con la fecha.","visita":"acceso libre","fuentes":["https://es.wikipedia.org/wiki/Garciaz"]},"t:iglesia-de-san-bartolome-apostol-herguijuela":{"municipio":"Herguijuela","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Herguijuela; el punto no marca el sitio exacto.","lat_pueblo":39.3745,"lon_pueblo":-5.7595,"resumen":"Iglesia parroquial de los siglos XVI-XVII.","visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Herguijuela_(Cáceres)"]},"t:iglesia-de-la-purisima-concepcion-madronera":{"municipio":"Madroñera","resumen":"Iglesia parroquial del siglo XVIII, de estilo barroco popular.","visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Madroñera","https://www.tuscasasrurales.com/que-ver-en-madronera-1770.htm"]},"t:mona-del-rollo-picota-de-madronera-madronera":{"municipio":"Madroñera","resumen":"Rollo o picota del tercer cuarto del siglo XVI, rematado con los blasones de los señores de la villa, que hoy forman el escudo de Madroñera. Es el escenario de la tradición de «poner la bandera» en la fiesta de los kintos, que se repite desde hacia 1908-1910.","ver_alli":["Blasones de los señores de la villa en el remate","Escenario de la fiesta de los kintos en febrero"],"visita":"acceso libre","fuentes":["https://es.wikipedia.org/wiki/Madroñera","https://www.tuscasasrurales.com/que-ver-en-madronera-1770.htm"]},"t:ermita-vieja-de-la-virgen-de-la-soterrana-madronera":{"municipio":"Madroñera","resumen":"Ermita de la patrona de Madroñera. Cuenta la leyenda que entre 1500 y 1600 la Virgen se apareció en una roca frente a la ermita a un pastor sorprendido por una tormenta de nieve y granizo, y le dio refugio en una cueva. Es tradición llevarse un trocito de pizarra del lugar y tirarlo al tejado de casa para protegerla de las tormentas.","ver_alli":["Roca de la aparición frente a la ermita","Tradición de llevarse un trozo de pizarra"],"visita":"desconocido","fuentes":["https://es.wikipedia.org/wiki/Madroñera","https://www.tuscasasrurales.com/que-ver-en-madronera-1770.htm"]},"t:cartel-de-nitrato-de-chile-de-madronera-madronera":{"municipio":"Madroñera","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Madroñera; el punto no marca el sitio exacto.","lat_pueblo":39.4254,"lon_pueblo":-5.7572,"resumen":"Cartel publicitario pintado en una fachada de la plaza (antigua plaza Calvo Sotelo) del fertilizante Nitrato de Chile, de hacia 1929. Lo diseñó Adolfo López-Durán Lozano, entonces estudiante de arquitectura formado en la Institución Libre de Enseñanza y luego catedrático en la Escuela de Arquitectura de Madrid. Es de estilo art déco, con gusto por lo geométrico.","ver_alli":["Diseño art déco de hacia 1929","Uno de los carteles de Nitrato de Chile de los pueblos agrícolas"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Madroñera"]},"t:plaza-de-toros-de-madronera-madronera":{"municipio":"Madroñera","resumen":"Plaza de toros del pueblo, recogida como recurso turístico por Turismo de Extremadura.","visita":"exterior libre","fuentes":["https://admin.turismoextremadura.juntaex.es/en/explora/Madronera-Bullring/?lang=en"]},"t:arco-entre-dos-casas-madronera":{"municipio":"Madroñera","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Madroñera; el punto no marca el sitio exacto.","lat_pueblo":39.4254,"lon_pueblo":-5.7572,"resumen":"Arco que une dos casas pasando por encima de una calle.","visita":"acceso libre","fuentes":["https://www.tuscasasrurales.com/que-ver-en-madronera-1770.htm"]},"t:iglesia-de-santa-catalina-de-alejandria-alcollarin":{"municipio":"Alcollarín","resumen":"Iglesia parroquial de finales del siglo XV y principios del XVI, construida por orden de Diego Pizarro. Tiene portada ojival, arcos apuntados y un ábside con bóveda de horno. La torre campanario de sillería es del siglo XVI y remata en una cornisa con balaustrada.","ver_alli":["Portada ojival","Torre de sillería con balaustrada","Ábside con bóveda de horno"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Iglesia_de_Santa_Catalina_de_Alejandría_(Alcollarín)","https://es.wikipedia.org/wiki/Alcollarín"]},"t:palacio-de-los-pizarro-carvajal-alcollarin":{"municipio":"Alcollarín","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Alcollarín; el punto no marca el sitio exacto.","lat_pueblo":39.2445,"lon_pueblo":-5.7381,"resumen":"Palacio del siglo XVI de los Pizarro-Carvajal, señores de Alcollarín. Los escudos que flanqueaban la fachada fueron robados en diciembre de 2001 y no se han recuperado. En su patio de armas se representó en las fiestas de agosto la obra «El Conde de Alcollarín».","ver_alli":["Fachada (huecos de los escudos robados en 2001)","Patio de armas"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Alcollarín"]},"t:iglesia-de-san-pablo-zorita":{"municipio":"Zorita","resumen":"Iglesia renacentista de mampostería con dos naves de cinco tramos, separadas por arcos apuntados y cubiertas con bóvedas de cañón con lunetos. Se entra por una portada ojival con alfiz y otra de medio punto a los pies. El retablo mayor se perdió, pero quedan algunas esculturas barrocas suyas.","ver_alli":["Portada ojival con alfiz","Ábside poligonal con crucería","Esculturas barrocas del antiguo retablo"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Zorita_(Cáceres)"]},"t:ermita-y-templete-de-fuente-santa-zorita":{"municipio":"Zorita","resumen":"Ermita de la patrona de Zorita, a unos 4 km del pueblo en la finca Las Caballerías, junto a un templete del siglo XVII. Es de una sola nave con bóveda de aristas y bóveda de horno sobre el altar, donde se venera la Virgen con el Niño. La Virgen baja al pueblo para las fiestas.","ver_alli":["Templete del siglo XVII","Imagen de Nuestra Señora de Fuente Santa"],"visita":"desconocido","fuentes":["https://es.wikipedia.org/wiki/Zorita_(Cáceres)"]},"t:casa-solariega-de-los-pizarro-zorita":{"municipio":"Zorita","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Zorita; el punto no marca el sitio exacto.","lat_pueblo":39.2853,"lon_pueblo":-5.7003,"resumen":"Casa solariega de los Pizarro en el pueblo.","visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Zorita_(Cáceres)"]},"t:casa-de-santa-maria-madrigalejo":{"municipio":"Madrigalejo","resumen":"Restos de la casa que el Monasterio de Guadalupe tenía en Madrigalejo, donde Fernando el Católico, de camino a Guadalupe y muy enfermo, firmó su testamento y murió el 23 de enero de 1516. Está declarada Monumento. Una placa en la fachada recuerda «Aquí falleció el muy alto y poderoso Rey don Fernando», y el pueblo usa el lema «Aquí murió el rey y nació España».","ver_alli":["Placa conmemorativa de la muerte del rey","Restos de la casa de los jerónimos de Guadalupe"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Madrigalejo","https://www.bbva.com/es/madrigalejo-pueblo-vio-morir-fernando-catolico/"]},"t:iglesia-de-san-juan-bautista-madrigalejo":{"municipio":"Madrigalejo","resumen":"Iglesia del siglo XVI, de buena factura, con una airosa torre campanario. Su pieza más valiosa es el retablo mayor plateresco con pinturas barrocas sobre tabla del siglo XVII.","ver_alli":["Retablo mayor plateresco","Pinturas sobre tabla del siglo XVII","Torre campanario"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Madrigalejo"]},"t:casas-palacio-de-madrigalejo-madrigalejo":{"municipio":"Madrigalejo","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Madrigalejo; el punto no marca el sitio exacto.","lat_pueblo":39.1369,"lon_pueblo":-5.6266,"resumen":"Casas-palacio de finales del siglo XIX y principios del XX junto a viviendas populares típicas.","visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Madrigalejo"]},"t:pizarro-poblado-de-colonizacion-campo-lugar":{"municipio":"Campo Lugar","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Campo Lugar; el punto no marca el sitio exacto.","lat_pueblo":39.1958,"lon_pueblo":-5.7711,"resumen":"Pedanía de Campo Lugar fundada en el siglo XX como poblado de colonización, con su iglesia de San Rafael.","visita":"acceso libre","fuentes":["https://es.wikipedia.org/wiki/Campo_Lugar","https://es.wikipedia.org/wiki/Pizarro_(Cáceres)"]},"t:el-helechal-logrosan":{"municipio":"Logrosán","resumen":"Antiguo lavadero donde se hacía la colada, hoy rehabilitado como paraje de merienda.","visita":"acceso libre","fuentes":["https://es.wikipedia.org/wiki/Logrosán"]},"t:puente-romano-de-logrosan-logrosan":{"municipio":"Logrosán","resumen":"Puente medieval pese a su nombre, interesante sobre todo por el paraje en que está.","visita":"acceso libre","fuentes":["https://es.wikipedia.org/wiki/Logrosán"]},"t:molino-del-rio-gibranzos-santa-ana":{"municipio":"Santa Ana","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Santa Ana; el punto no marca el sitio.","lat_pueblo":39.309,"lon_pueblo":-5.9902,"resumen":"Antiguo molino harinero a orillas del río Gibranzos, en la dehesa boyal.","visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Santa_Ana_(Cáceres)"]},"t:la-puente-la-cumbre":{"municipio":"La Cumbre","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de La Cumbre; el punto no marca el sitio.","lat_pueblo":39.405,"lon_pueblo":-5.9771,"resumen":"Puente antiguo conocido como «La Puente».","visita":"acceso libre","fuentes":["https://es.wikipedia.org/wiki/La_Cumbre_(Cáceres)"]},"t:torre-del-reloj-ibahernando":{"municipio":"Ibahernando","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Ibahernando; el punto no marca el sitio.","lat_pueblo":39.3167,"lon_pueblo":-5.9167,"resumen":"Torre del reloj de 1892, antiguo ayuntamiento y hoy biblioteca municipal.","visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Ibahernando"]},"t:puente-del-romero-miajadas":{"municipio":"Miajadas","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Miajadas; el punto no marca el sitio.","lat_pueblo":39.1528,"lon_pueblo":-5.9081,"resumen":"Puente sobre el río Búrdalo construido entre 1779 y 1782, en tiempos de Carlos III, a propuesta de Campomanes; antes hubo uno de madera hecho en 1777 para el paso de la reina madre de Portugal. Lo proyectó Marcos de Vierna y costó 500.000 reales que pagaron Miajadas, Almoharín y Medellín.","ver_alli":["Fábrica del siglo XVIII sobre el Búrdalo"],"visita":"acceso libre","fuentes":["https://sites.google.com/educarex.es/patrimoniomiajadas/inicio/puente-del-romero"]},"t:ermita-del-santo-escurial":{"municipio":"Escurial","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Escurial; el punto no marca el sitio.","lat_pueblo":39.1694,"lon_pueblo":-5.8856,"resumen":"Ermita a la que se va en romería el Lunes de Pascua.","visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Escurial"]},"t:ermita-de-san-marcos-valhondo-puerto-de-santa-cruz":{"municipio":"Puerto de Santa Cruz","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Puerto de Santa Cruz; el punto no marca el sitio.","lat_pueblo":39.3163,"lon_pueblo":-5.8588,"resumen":"Ermita en el paraje de Valhondo, antigua propiedad de los duques de San Carlos, donde se celebra la romería de San Marcos; quedan cerca restos de un poblado antiguo.","visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Puerto_de_Santa_Cruz"]},"t:ruinas-de-la-sierra-de-santa-cruz-santa-cruz-de-la-sierra":{"municipio":"Santa Cruz de la Sierra","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Santa Cruz de la Sierra; el punto no marca el sitio.","lat_pueblo":39.3361,"lon_pueblo":-5.8458,"resumen":"Zona arqueológica declarada Bien de Interés Cultural en 1931 en la sierra que domina el pueblo, con restos de distintas épocas, entre ellos una piedra conocida como altar neolítico.","ver_alli":["Piedra del «altar neolítico»"],"visita":"desconocido","fuentes":["https://es.wikipedia.org/wiki/Anexo:Bienes_de_interés_cultural_de_la_provincia_de_Cáceres"]},"t:ermita-de-la-caridad-garciaz":{"municipio":"Garciaz","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Garciaz; el punto no marca el sitio.","lat_pueblo":39.4136,"lon_pueblo":-5.6267,"resumen":"Capilla del antiguo hospital de la Cofradía de la Caridad, fundada en 1574; la casa-hospital se compró en 1612 y funcionó hasta 1846, cuando pasó a escuelas. La capilla sigue en uso como ermita, con techo de madera a dos aguas y un presbiterio con cúpula que lleva una inscripción latina.","ver_alli":["Virgen con el Niño de finales del siglo XV","Portada renacentista","Ventana con rejería típica"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Garciaz"]},"t:ermita-de-la-concepcion-garciaz":{"municipio":"Garciaz","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Garciaz; el punto no marca el sitio.","lat_pueblo":39.4136,"lon_pueblo":-5.6267,"resumen":"Ermita junto al antiguo camino de Berzocana, de planta rectangular con ábside, patrocinada por el obispo Gutierre de Vargas Carvajal (1506-1559), cuyos escudos aparecen en las claves de los arcos. Se abandonó en el siglo XIX, sirvió de cementerio en 1821-1823 y ha sido reconstruida hace pocos años.","ver_alli":["Restos de esgrafiado de la Anunciación en el ábside","Escudos del obispo en las claves"],"visita":"desconocido","fuentes":["https://es.wikipedia.org/wiki/Garciaz"]},"t:ermita-de-portera-garciaz":{"municipio":"Garciaz","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Garciaz; el punto no marca el sitio.","lat_pueblo":39.4136,"lon_pueblo":-5.6267,"resumen":"Restos de una ermita en los Campos de Portera cuyo origen se remonta al siglo VII y que tuvo uso religioso al menos hasta el XVIII. Tiene una cabecera con bóveda peraltada decorada con esgrafiados de los siglos XVI-XVII y piezas tardoantiguas reaprovechadas; en un pilar está empotrado el epitafio romano de Annia. Está en ruina y se usó como encierro de ganado.","ver_alli":["Cabecera abovedada con esgrafiados","Lápida funeraria romana de Annia","Piezas tardoantiguas en los muros"],"visita":"desconocido","fuentes":["https://es.wikipedia.org/wiki/Garciaz"]},"t:puente-de-las-tres-lanchas-garciaz":{"municipio":"Garciaz","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Garciaz; el punto no marca el sitio.","lat_pueblo":39.4136,"lon_pueblo":-5.6267,"resumen":"Puentecillo rústico a las afueras, junto al camino de La Concepción o de Berzocana, hecho con tres grandes lajas de pizarra apoyadas en estribos de mampostería. Las lanchas conservan grafitos y letras grabadas a lo largo del tiempo.","ver_alli":["Tres losas de pizarra como tablero","Grafitos grabados en las lanchas"],"visita":"acceso libre","fuentes":["https://es.wikipedia.org/wiki/Garciaz"]},"t:puentes-de-la-villa-y-de-la-hoya-garciaz":{"municipio":"Garciaz","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Garciaz; el punto no marca el sitio.","lat_pueblo":39.4136,"lon_pueblo":-5.6267,"resumen":"Puentes de mampostería de pizarra en torno al pueblo, algunos del siglo XVII como el de la Villa o el de la Hoya.","visita":"acceso libre","fuentes":["https://es.wikipedia.org/wiki/Garciaz"]},"t:antigua-almazara-de-garciaz-garciaz":{"municipio":"Garciaz","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Garciaz; el punto no marca el sitio.","lat_pueblo":39.4136,"lon_pueblo":-5.6267,"resumen":"Almazara cooperativa de la segunda mitad del siglo XX junto al Charco del Caño, que aún conserva pilas, molino, caldera y prensa.","visita":"desconocido","fuentes":["https://es.wikipedia.org/wiki/Garciaz"]},"t:grabados-rupestres-de-el-candalo-garciaz":{"municipio":"Garciaz","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Garciaz; el punto no marca el sitio.","lat_pueblo":39.4136,"lon_pueblo":-5.6267,"resumen":"Grabados incisos sobre un afloramiento de pizarra en la finca del Cándalo, cerca de El Venero, de la Edad del Bronce Medio-Final. Representan armas (alabardas, flechas, hachas, lanzas, espadas), formas estelares radiadas y líneas abstractas, reflejo de la llegada de la metalurgia. Están declarados BIC.","ver_alli":["Motivos de armas grabados en pizarra","Formas estelares radiadas"],"visita":"desconocido","fuentes":["https://es.wikipedia.org/wiki/Garciaz"]},"t:castro-de-valdeagudo-garciaz":{"municipio":"Garciaz","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Garciaz; el punto no marca el sitio.","lat_pueblo":39.4136,"lon_pueblo":-5.6267,"resumen":"Restos de un poblado vetón de cabañas circulares rodeado de muralla, en uno de los cerros más altos del entorno.","visita":"desconocido","fuentes":["https://es.wikipedia.org/wiki/Garciaz"]},"t:ermita-del-cerro-madronera":{"municipio":"Madroñera","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Madroñera; el punto no marca el sitio.","lat_pueblo":39.4254,"lon_pueblo":-5.7572,"resumen":"Ermita situada dentro del casco urbano.","visita":"desconocido","fuentes":["https://www.tuscasasrurales.com/que-ver-en-madronera-1770.htm"]},"t:pareanos-de-malillo-zorita":{"municipio":"Zorita","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Zorita; el punto no marca el sitio.","lat_pueblo":39.2853,"lon_pueblo":-5.7003,"resumen":"Ruinas de un antiguo convento junto al arroyo Malillo, del que se sabe poco.","visita":"desconocido","fuentes":["https://es.wikipedia.org/wiki/Zorita_(Cáceres)"]},"t:ermita-de-la-virgen-de-las-angustias-madrigalejo":{"municipio":"Madrigalejo","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Madrigalejo; el punto no marca el sitio.","lat_pueblo":39.1369,"lon_pueblo":-5.6266,"resumen":"Ermita barroca del siglo XVIII, sencilla pero cuidada.","visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Madrigalejo"]}});